// Generated by conjecture - do not edit. It is rewritten on every check.
//
// Reads conjecture_input.json, calls the static entry method named on
// the command line ("com.acme.Pricing:changeFee") with the inputs as a
// Map<String, String> (names without the "input." prefix), and writes
// what it returns (a Map, names without the "output." prefix) to
// conjecture_output.json.
import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.LinkedHashMap;
import java.util.Map;

public final class ConjectureAdapter {
    public static void main(String[] args) throws Exception {
        String entry = args.length > 0 ? args[0] : "";
        int cut = entry.lastIndexOf(':');
        if (cut <= 0 || cut == entry.length() - 1) {
            fail("entry must be package.Class:method, got \"" + entry + "\"");
        }
        Class<?> type = Class.forName(entry.substring(0, cut));
        Method method = type.getMethod(entry.substring(cut + 1), Map.class);

        String text = new String(Files.readAllBytes(Paths.get("conjecture_input.json")), StandardCharsets.UTF_8);
        Map<String, String> inputs = new LinkedHashMap<>();
        for (Map.Entry<String, String> e : parseFlatObject(text).entrySet()) {
            if (e.getKey().startsWith("input.")) {
                inputs.put(e.getKey().substring("input.".length()), e.getValue());
            }
        }

        Object result = method.invoke(null, inputs);
        if (!(result instanceof Map)) {
            fail(entry + " must return a Map of output name to value");
        }

        StringBuilder out = new StringBuilder("{");
        boolean first = true;
        for (Map.Entry<?, ?> e : ((Map<?, ?>) result).entrySet()) {
            if (!first) {
                out.append(',');
            }
            first = false;
            out.append(quote("output." + e.getKey())).append(':').append(quote(String.valueOf(e.getValue())));
        }
        out.append('}');
        Files.write(Paths.get("conjecture_output.json"), out.toString().getBytes(StandardCharsets.UTF_8));
    }

    private static void fail(String message) {
        System.err.println("conjecture adapter: " + message);
        System.exit(2);
    }

    // conjecture_input.json is always one flat JSON object of string to
    // string, written by conjecture itself - this parser reads exactly
    // that shape and nothing more, so the adapter needs no JSON library
    // on the classpath.
    private static Map<String, String> parseFlatObject(String s) {
        Map<String, String> out = new LinkedHashMap<>();
        int[] pos = {0};
        skipSpace(s, pos);
        expect(s, pos, '{');
        skipSpace(s, pos);
        if (s.charAt(pos[0]) == '}') {
            return out;
        }
        while (true) {
            skipSpace(s, pos);
            String key = readString(s, pos);
            skipSpace(s, pos);
            expect(s, pos, ':');
            skipSpace(s, pos);
            out.put(key, readString(s, pos));
            skipSpace(s, pos);
            char c = s.charAt(pos[0]++);
            if (c == '}') {
                return out;
            }
            if (c != ',') {
                throw new IllegalArgumentException("conjecture_input.json: expected ',' or '}' at " + (pos[0] - 1));
            }
        }
    }

    private static void skipSpace(String s, int[] pos) {
        while (pos[0] < s.length() && Character.isWhitespace(s.charAt(pos[0]))) {
            pos[0]++;
        }
    }

    private static void expect(String s, int[] pos, char want) {
        if (s.charAt(pos[0]) != want) {
            throw new IllegalArgumentException("conjecture_input.json: expected '" + want + "' at " + pos[0]);
        }
        pos[0]++;
    }

    private static String readString(String s, int[] pos) {
        expect(s, pos, '"');
        StringBuilder b = new StringBuilder();
        while (true) {
            char c = s.charAt(pos[0]++);
            if (c == '"') {
                return b.toString();
            }
            if (c != '\\') {
                b.append(c);
                continue;
            }
            char e = s.charAt(pos[0]++);
            switch (e) {
                case 'n': b.append('\n'); break;
                case 't': b.append('\t'); break;
                case 'r': b.append('\r'); break;
                case 'b': b.append('\b'); break;
                case 'f': b.append('\f'); break;
                case 'u':
                    b.append((char) Integer.parseInt(s.substring(pos[0], pos[0] + 4), 16));
                    pos[0] += 4;
                    break;
                default: b.append(e);
            }
        }
    }

    private static String quote(String s) {
        StringBuilder b = new StringBuilder("\"");
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': b.append("\\\""); break;
                case '\\': b.append("\\\\"); break;
                case '\n': b.append("\\n"); break;
                case '\r': b.append("\\r"); break;
                case '\t': b.append("\\t"); break;
                default:
                    if (c < 0x20) {
                        b.append(String.format("\\u%04x", (int) c));
                    } else {
                        b.append(c);
                    }
            }
        }
        return b.append('"').toString();
    }
}
